// #94c3ab (6a993d738eac0db9d694c3ab) «פיתוח: ניהול גרסאות וסטטוסים של סימולציה» — состояния «נעולה» / нет активной / пустой список
// через ПОДМЕНУ ответов GET simulations (route.fetch + правка или fulfill). Кейсы STAT-001…STAT-005.
// Сервер не меняется: голосовые звонки не стартуют, статусы симуляций не переключаются; create_candidate и
// записи симуляций обрываются и должны быть вызваны 0 раз. Только десктоп (L-20261014-5). Все — @prod-safe.
import { test, expect } from '@playwright/test';
import { openWithApi } from '../support/api';
import { HASH, MANAGER_STATE, RECRUITER_STATE, mockSimulationsList, lockOneRow, mockEditorLocked, mockInviteSimulations, blockCandidateCreation, blockSimulationWrites, openInviteDrawer } from './support';

test.describe(`Статусы симуляции — «נעולה» и пустые состояния, менеджер аккаунта, подмена GET simulations (${HASH})`, () => {
  test.use({ storageState: MANAGER_STATE });

  test(`STAT-001: список /simulations, одна строка заперта → «נעולה» + «ניסיון אחד בתהליך — עריכה חסומה», чип «נעולות 1», у строки нет меню действий @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const box: { id?: string; lockedTotal?: number } = {};
    await mockSimulationsList(page, lockOneRow(box));
    const writes = await blockSimulationWrites(page);
    await page.goto('/simulations');

    await expect(page.locator('[data-simulation-id]').first()).toBeVisible();
    test.skip(!box.id, 'окружение: у testim нет ни одной симуляции — нечего запирать');
    const locked = page.locator(`[data-simulation-id="${box.id}"]`);
    await expect(locked).toBeVisible();

    // Источник: AC2 «в списке каждая симуляция со статусом»; abb5d9c 17.11 (M6-SIMLOCK-AC1).
    await expect(locked).toContainText('נעולה');
    await expect(locked).toContainText('ניסיון אחד בתהליך — עריכה חסומה');
    // Чип «נעולות N» и сводка под заголовком.
    await expect(page.locator('main').getByText(new RegExp(`נעולות\\s*${box.lockedTotal}(?!\\d)`)).first()).toBeVisible();
    if (box.lockedTotal === 1) await expect(page.locator('main').getByText(/1\s+נעולה/).first()).toBeVisible();
    // У запертой строки нет меню действий (нельзя деактивировать/менять статус).
    await expect(locked.getByRole('button', { name: /^פעולות/ })).toHaveCount(0);
    expect(writes(), 'статусы симуляций не должны меняться').toBe(0);
  });

  test(`STAT-002: редактор запертой симуляции (подмена) → без полей, «הסימולציה נעולה…», «למועמדים המשויכים» ведёт на /candidates?simulation=<id> @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/simulations');
    const sims = (await (await api.get('simulations?select=id,status,version,name&order=updated_at.desc')).json()) as { id: string; status: string }[];
    const sim = sims.find((s) => s.status === 'active') ?? sims.find((s) => s.status !== 'locked');
    test.skip(!sim, 'окружение: у testim нет симуляций');
    await mockEditorLocked(page, sim!.id);
    const writes = await blockSimulationWrites(page);
    await page.goto(`/simulations/${sim!.id}`);

    // Источник: AC3 «נעולה — עריכה נחסמת עם הסבר», FL-20 «הסבר… וקישור לרשימת המועמדים המשויכים».
    await expect(page.getByText('הסימולציה נעולה', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('הסימולציה נעולה בשל ניסיונות פעילים, ולכן לא ניתן לערוך אותה.')).toBeVisible();
    await expect(page.getByText('אפשר לערוך אותה שוב כשהניסיונות יסתיימו.')).toBeVisible();
    // Полей ввода нет — только чтение.
    await expect(page.locator('main').locator('input:not([type=hidden]), textarea, select')).toHaveCount(0);

    const link = page.getByRole('link', { name: 'למועמדים המשויכים' });
    await expect(link).toBeVisible();
    await expect(link).toHaveAttribute('href', `/candidates?simulation=${sim!.id}`);
    await link.click();
    await expect(page).toHaveURL(new RegExp(`/candidates\\?simulation=${sim!.id}`));
    expect(writes(), 'статусы симуляций не должны меняться').toBe(0);
  });

  test(`STAT-003: «הזמנת מועמד», единственная симуляция заперта (подмена) → «הסימולציה «…» נעולה בשל ניסיונות פעילים», «אפשר יהיה לשייך…», «לרשימת הסימולציות»; кандидат не создаётся @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const name = 'QA-AUTO-94c3ab נעולה';
    await mockInviteSimulations(page, [{ id: '00000000-0000-0000-0000-000000000095', name, version: 2, role_title: 'QA-AUTO נציג/ת', status: 'locked' }]);
    const created = await blockCandidateCreation(page);
    await page.goto('/candidates');
    await openInviteDrawer(page);

    // Источник: דרישה 6 «נעולה/לא פעילה חוסמת שיוך», abb5d9c 17.11 (M6-SIMLOCK).
    const notice = page.getByTestId('no-assignable-simulation');
    await expect(notice).toBeVisible();
    await expect(notice).toContainText(`הסימולציה «${name}» נעולה בשל ניסיונות פעילים`);
    await expect(notice).toContainText('אפשר יהיה לשייך אליה מועמדים חדשים כשהניסיונות יסתיימו.');
    const link = notice.getByRole('link', { name: 'לרשימת הסימולציות' });
    await expect(link).toHaveAttribute('href', '/simulations');
    // Поля выбора симуляции нет — приглашать некого.
    await expect(page.getByRole('combobox', { name: /סימולציה/ })).toHaveCount(0);
    expect(created(), 'create_candidate не должен вызываться').toBe(0);
  });
});

test.describe(`Статусы симуляции — рекрутер без активной симуляции, подмена GET simulations (${HASH})`, () => {
  test.use({ storageState: RECRUITER_STATE });

  test(`STAT-004: מנהל/ת מגייס/ת, активных и запертых нет (подмена []) → «אין סימולציה פעילה…» + «לרשימת הסימולציות»; кандидат не создаётся @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await mockInviteSimulations(page, []);
    const created = await blockCandidateCreation(page);
    await page.goto('/candidates');
    await openInviteDrawer(page);

    // Источник: AC4 «назначение блокируется, предлагается включить или выбрать другую»; для рекрутера — обращение к מנהל/ת החשבון.
    const notice = page.getByTestId('no-assignable-simulation');
    await expect(notice).toBeVisible();
    await expect(notice).toContainText('אין סימולציה פעילה');
    await expect(notice).toContainText('מועמד/ת משויך/ת תמיד לסימולציה פעילה. יש להפעיל סימולציה (או לבקש ממנהל/ת החשבון לשייך אליך סימולציה פעילה) ואז לחזור לכאן.');
    await expect(notice.getByRole('link', { name: 'לרשימת הסימולציות' })).toHaveAttribute('href', '/simulations');
    expect(created(), 'create_candidate не должен вызываться').toBe(0);
  });
});

test.describe(`Статусы симуляции — пустой список /simulations, подмена [] (${HASH})`, () => {
  test.use({ storageState: MANAGER_STATE });

  test(`STAT-005: пустой список на 1440 → карточка 1104×271, «יצירת סימולציה» высота 44, «שימוש בתבנית» высота 40; на 390 нет горизонтальной прокрутки @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await mockSimulationsList(page, () => []);
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/simulations');
    await expect(page.getByText('עדיין אין סימולציות', { exact: true })).toBeVisible();

    const m = await page.evaluate(() => {
      const h = [...document.querySelectorAll('main *')].find((e) => e.children.length === 0 && e.textContent?.trim() === 'עדיין אין סימולציות') as HTMLElement | undefined;
      if (!h) return null;
      let card: HTMLElement | null = h.parentElement;
      while (card && card.getBoundingClientRect().width < 1000) card = card.parentElement;
      if (!card) return null;
      const c = card.getBoundingClientRect();
      const inside = (b: Element) => {
        const r = b.getBoundingClientRect();
        return r.top >= c.top && r.bottom <= c.bottom && r.left >= c.left && r.right <= c.right;
      };
      const items = [...document.querySelectorAll('main a, main button')];
      const create = items.find((b) => /יצירת סימולציה/.test(b.textContent || '') && inside(b));
      const tpl = items.find((b) => /שימוש בתבנית/.test(b.textContent || ''));
      return {
        card: { w: c.width, h: c.height },
        create: create ? { h: create.getBoundingClientRect().height } : null,
        tpl: tpl ? { h: tpl.getBoundingClientRect().height } : null,
      };
    });
    expect(m, 'карточка пустого состояния не найдена').not.toBeNull();
    // Источник: Figma 864:3646, реджект 5 (04.11): 1104×271; кнопки 44 и 40 (ширины зависят от шрифта — не проверяются).
    expect(Math.abs(m!.card.w - 1104), `карточка ${m!.card.w}×${m!.card.h}`).toBeLessThanOrEqual(2);
    expect(Math.abs(m!.card.h - 271), `карточка ${m!.card.w}×${m!.card.h}`).toBeLessThanOrEqual(2);
    expect(Math.round(m!.create!.h), '«יצירת סימולציה» в карточке').toBe(44);
    expect(Math.round(m!.tpl!.h), '«שימוש בתבנית»').toBe(40);

    // Мобильная ширина: окно 390 без эмуляции телефона (экран бизнеса — только десктоп).
    await page.setViewportSize({ width: 390, height: 844 });
    await expect(page.getByText('עדיין אין סימולציות', { exact: true })).toBeVisible();
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    expect(overflow, 'горизонтальная прокрутка на 390').toBeLessThanOrEqual(0);
  });
});
